import random

def generate_d9_graph(N):
    # Generates an adjacency list representation for a directed graph G=(V, E)
    # where |V| = N and out-degree(v) = 9 for all v.
    if N <= 9:
        return None # Cannot achieve out-degree 9 if N <= 9

    graph = {i: [] for i in range(N)}

    # Ensure every vertex has out-degree exactly 9
    for i in range(N):
        # Select 9 distinct neighbors (excluding self)
        neighbors = random.sample([j for j in range(N) if j != i], 9)
        graph[i] = neighbors

    return graph

def verify_d9(graph):
    # Verifies that every vertex in the graph has an out-degree of exactly 9.
    N = len(graph)
    if N == 0:
        return True

    all_ok = True
    for v in range(N):
        if len(graph[v]) != 9:
            print(f"Vertex {v} has out-degree {len(graph[v])}, expected 9.")
            all_ok = False

    if all_ok:
        print("Verification successful: All vertices have out-degree 9.")
    return all_ok

# Test case: N=10 (the smallest case where d_out=9 is possible)
N_test = 10
print(f"--- Testing Small Graph N={N_test} ---")
graph_10 = generate_d9_graph(N_test)

if graph_10:
    verify_d9(graph_10)
else:
    print("Graph generation failed for N=10 (should not happen).")

